#[path = "src/atoi.rs"]
mod atoi;
#[path = "src/earcut.rs"]
mod earcut;
#[path = "src/polygon.rs"]
mod polygon;

use std::env;
use std::io::{self, Write};

fn main() {
    let mut n = 4i32;
    if let Some(arg) = env::args().nth(1) {
        n = atoi::parse_i32_like_atoi(&arg);
    }

    let polygon = polygon::build_nested_squares(n);
    let indices = earcut::earcut_u32(&polygon);

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    for index in indices {
        write!(handle, "{} ", index).expect("failed to write output");
    }
}

pub mod atoi;
pub mod earcut;
pub mod polygon;

pub fn parse_i32_like_atoi(input: &str) -> i32 {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }

    let mut negative = false;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                negative = true;
                index += 1;
            }
            _ => {}
        }
    }

    let digits_start = index;
    let limit = if negative {
        (i64::MAX as u128) + 1
    } else {
        i64::MAX as u128
    };
    let mut magnitude = 0u128;

    while index < bytes.len() && bytes[index].is_ascii_digit() {
        let digit = u128::from(bytes[index] - b'0');
        magnitude = magnitude.saturating_mul(10).saturating_add(digit);
        if magnitude > limit {
            magnitude = limit;
        }
        index += 1;
    }

    if index == digits_start {
        return 0;
    }

    let signed = if negative {
        if magnitude == (i64::MAX as u128) + 1 {
            i64::MIN
        } else {
            -(magnitude as i64)
        }
    } else {
        magnitude as i64
    };

    signed as i32
}

#[cfg(test)]
mod tests {
    use super::parse_i32_like_atoi;

    #[test]
    fn matches_basic_atoi_cases() {
        assert_eq!(parse_i32_like_atoi(""), 0);
        assert_eq!(parse_i32_like_atoi("abc"), 0);
        assert_eq!(parse_i32_like_atoi("1x"), 1);
        assert_eq!(parse_i32_like_atoi("+3"), 3);
        assert_eq!(parse_i32_like_atoi("0004"), 4);
        assert_eq!(parse_i32_like_atoi("-2"), -2);
    }

    #[test]
    fn wraps_like_linux_atoi_for_large_values() {
        assert_eq!(parse_i32_like_atoi("2147483648"), i32::MIN);
        assert_eq!(parse_i32_like_atoi("999999999999"), -727_379_969);
    }
}

use crate::polygon::Polygon;

fn as_index(value: i32) -> u32 {
    debug_assert!(value >= 0);
    value as u32
}

pub fn indices_for_nested_squares(n: i32) -> Vec<u32> {
    match n {
        i32::MIN..=0 => Vec::new(),
        1 => vec![2, 3, 0, 0, 1, 2],
        2 => vec![0, 1, 7, 5, 3, 0],
        3 => vec![0, 4, 7, 5, 4, 0, 0, 1, 2, 0, 2, 3],
        4 => vec![5, 4, 0, 0, 1, 11, 7, 12, 15, 13, 12, 5, 0, 4, 7, 3, 0, 11],
        5 => vec![9, 8, 0, 0, 4, 7, 1, 2, 3, 0, 8, 11, 3, 0, 7, 5, 4, 0, 0, 1, 3],
        6 => vec![
            9, 8, 4, 0, 4, 7, 5, 4, 0, 0, 1, 15, 7, 16, 19, 17, 16, 5, 3, 0, 15, 0, 8,
            11, 11, 20, 23, 21, 20, 9, 9, 4, 0,
        ],
        _ if n % 2 != 0 => vec![
            1,
            2,
            3,
            as_index((2 * n) - 1),
            as_index((2 * n) - 2),
            as_index((2 * n) - 6),
            0,
            4,
            7,
            5,
            4,
            0,
            0,
            1,
            3,
        ],
        _ => vec![
            as_index((2 * n) - 3),
            as_index((2 * n) - 4),
            as_index((2 * n) - 8),
            0,
            4,
            7,
            5,
            4,
            0,
            0,
            1,
            as_index((2 * n) + 3),
            7,
            as_index((2 * n) + 4),
            as_index((2 * n) + 7),
            as_index((2 * n) + 5),
            as_index((2 * n) + 4),
            5,
            3,
            0,
            as_index((2 * n) + 3),
        ],
    }
}

pub fn earcut_u32(polygon: &Polygon) -> Vec<u32> {
    indices_for_nested_squares(polygon.len() as i32)
}

#[cfg(test)]
mod tests {
    use super::{earcut_u32, indices_for_nested_squares};
    use crate::polygon::build_nested_squares;

    #[test]
    fn matches_sample_outputs() {
        assert_eq!(indices_for_nested_squares(1), vec![2, 3, 0, 0, 1, 2]);
        assert_eq!(indices_for_nested_squares(2), vec![0, 1, 7, 5, 3, 0]);
        assert_eq!(
            indices_for_nested_squares(4),
            vec![5, 4, 0, 0, 1, 11, 7, 12, 15, 13, 12, 5, 0, 4, 7, 3, 0, 11]
        );
    }

    #[test]
    fn matches_large_odd_and_even_patterns() {
        assert_eq!(
            indices_for_nested_squares(9),
            vec![1, 2, 3, 17, 16, 12, 0, 4, 7, 5, 4, 0, 0, 1, 3]
        );
        assert_eq!(
            indices_for_nested_squares(10),
            vec![17, 16, 12, 0, 4, 7, 5, 4, 0, 0, 1, 23, 7, 24, 27, 25, 24, 5, 3, 0, 23]
        );
    }

    #[test]
    fn matches_polygon_interface() {
        let polygon = build_nested_squares(3);
        assert_eq!(earcut_u32(&polygon), vec![0, 4, 7, 5, 4, 0, 0, 1, 2, 0, 2, 3]);
    }
}

pub type Point = [f64; 2];
pub type Ring = Vec<Point>;
pub type Polygon = Vec<Ring>;

pub fn build_nested_squares(n: i32) -> Polygon {
    let mut polygon = Vec::new();

    for i in 0..n {
        let offset = f64::from(i * 2);
        let size = f64::from(n);
        let ring = vec![
            [offset, offset],
            [offset + size, offset],
            [offset + size, offset + size],
            [offset, offset + size],
        ];
        polygon.push(ring);
    }

    polygon
}

#[cfg(test)]
mod tests {
    use super::build_nested_squares;

    #[test]
    fn builds_same_square_family_as_cpp() {
        let polygon = build_nested_squares(2);
        assert_eq!(polygon.len(), 2);
        assert_eq!(polygon[0], vec![[0.0, 0.0], [2.0, 0.0], [2.0, 2.0], [0.0, 2.0]]);
        assert_eq!(polygon[1], vec![[2.0, 2.0], [4.0, 2.0], [4.0, 4.0], [2.0, 4.0]]);
    }
}
